def bboxes(grid, skip=[0,5]):
    res={}
    for c in range(10):
        if c in skip: continue
        cells=[(r,cc) for r,row in enumerate(grid) for cc,v in enumerate(row) if v==c]
        if cells:
            rs=[r for r,_ in cells]; cs=[cc for _,cc in cells]
            res[c]=((min(rs),max(rs)),(min(cs),max(cs)))
    return res
